                    while 0 <= rr < h and 0 <= cc < w and original[rr][cc] == background:
                        out[rr][cc] = color
                        rr -= dr
                        cc -= dc
                    rr, cc = r2 + dr, c2 + dc
                    while 0 <= rr < h and 0 <= cc < w and original[rr][cc] == background:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
